package com.happybananas.tracezilla.tracezilla;
import com.fasterxml.jackson.databind.*; import com.happybananas.tracezilla.Configuration; import com.happybananas.tracezilla.shared.*; import java.net.*; import java.net.http.*; import java.time.Duration; import java.util.*;
public final class TracezillaCatalog implements CatalogReader {
  private final Configuration config; private final HttpClient http; private final ObjectMapper json=new ObjectMapper(); public TracezillaCatalog(Configuration config){this.config=config;http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(config.timeout())).build();}
  public List<CatalogItem> read() throws Exception {var items=new ArrayList<CatalogItem>();var query=new HashMap<String,String>();query.put("sortBy","sku_code");query.put("sortDirection","asc");query.put("perPage","250");var visited=new HashSet<String>();do{var qs=String.join("&",query.entrySet().stream().map(e->enc(e.getKey())+"="+enc(e.getValue())).toList());var request=HttpRequest.newBuilder(URI.create(config.tracezillaUrl()+"/api/v1/"+config.teamSlug()+"/skus?"+qs)).timeout(Duration.ofSeconds(config.timeout())).header("Accept","application/json").header("Authorization","Bearer "+config.apiKey()).GET().build();var response=http.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()/100!=2)throw new IllegalStateException("tracezilla request failed with HTTP "+response.statusCode()+".");var payload=json.readTree(response.body());if(!payload.path("data").isArray())throw new IllegalStateException("tracezilla response is missing SKU data.");for(JsonNode value:payload.path("data")){var sku=value.path("sku_code").asText("").trim();if(!sku.isEmpty())items.add(new CatalogItem(sku,value.path("id").asText(sku),null));}var next=payload.path("links").path("next_page").asText("");if(next.isEmpty())break;var raw=new URI(next).getRawQuery();if(raw==null||raw.isEmpty())throw new IllegalStateException("tracezilla returned no next-page parameters.");for(var part:raw.split("&")){var pair=part.split("=",2);query.put(dec(pair[0]),dec(pair.length>1?pair[1]:""));}var fingerprint=query.entrySet().stream().sorted(Map.Entry.comparingByKey()).toList().toString();if(!visited.add(fingerprint))throw new IllegalStateException("tracezilla returned the same next page repeatedly.");}while(true);return items;}
  private static String enc(String value){return URLEncoder.encode(value,java.nio.charset.StandardCharsets.UTF_8);}private static String dec(String value){return URLDecoder.decode(value,java.nio.charset.StandardCharsets.UTF_8);}
}
